// Inhaber-Entscheidung Nr. 32 (31.10.2026): alle aktuell lieferbaren Artikel des
// offiziellen Assouline-Shops für Österreich/EU (https://eu.assouline.com, Währung EUR,
// Lieferland „AT (€)“). Welt "accessoires", bereich "accessoires".
//
// Quelle der Produktliste: öffentliche Shopify-Produktliste des EU-Shops
// (https://eu.assouline.com/products.json, 578 Produkte) abgeglichen mit der
// Produkt-Sitemap (robots.txt → sitemap.xml → sitemap_products_1.xml, 551 URLs).
// Fakten je Artikel aus der Produktseite selbst (Lieferland AT): Kollektion über dem
// Titel (→ serie), Tabelle „In the details“ (Seitenzahl, Abbildungen, Sprache,
// Erscheinungsmonat, Maße in cm, Einband, ISBN, Gewicht, Autor) und angezeigter Preis.
// Normale HTTP-Abrufe, kein gefälschter User-Agent, ~2,5 s Pause, robots.txt beachtet.
// Vollständigkeits-Check: qa-screenshots/wellness/produkte/vollstaendigkeit-assouline.md.
//
// Umfang: 483 lieferbare Artikel (> 300) → im Code nach Reihe (= Kollektion
// laut Produktseite, Feld serie) gegliedert. Nicht erfasst (mit Grund im Check):
// ausverkaufte Titel („Currently Unavailable“), Vorbestell-/„Coming Soon“-Titel,
// Geschenkverpackungen/Tragetaschen mit Preis 0, als nicht kaufbar markierte Zugaben.
// Ein Eintrag je Produktseite: Der Shop führt Ausgaben (Classic/Ultimate/XXL,
// Sprachen, Farben) als eigene Produktseiten mit eigenem Preis; die Auswahlleiste
// („Select a TYPE/EDITION“) verlinkt nur auf diese Seiten → eigene Einträge.
//
// Preise: angezeigter Preis der Produktseite mit Lieferland AT, EUR, Stand 31.10.2026.
// Der EU-Shop nennt auf der Produktseite keinen ausdrücklichen MwSt.-Hinweis
// (Hilfe-Center: Steuern werden ggf. im Checkout ausgewiesen) → Übergabe an den
// Koordinator. Nichts geschätzt. Optionale Shop-Felder je Variante nur aus dem Shop:
// sku = Artikelnummer des Shops (bei Büchern die ISBN), versandGewichtG = Gewicht des
// Shop-Artikels (Shopify-Feld „grams“, nur wenn > 0). Keine Versandmaße (der Shop nennt
// nur Buchmaße, keine Paketmaße). Bücher sind nicht als zerbrechlich markiert.
//
// Texte: eigene Kurztexte aus den belegten Fakten (Titel, Reihe, Seitenzahl, Sprache,
// Ausführung); keine Klappentexte. Autoren als Merkmal (nicht im Feld designer).
// Einband: Schlagworte aus „Cover materials“ (Hardcover, Kassette, Schuber, Materialien),
// längere Werbetexte dort werden nicht übernommen. Maße wie im Shop (W × L × D, cm).
// Bilder: erstes Produktbild (Cover/Packshot) der Shop-CDN (cdn.shopify.com, Shop-Dateien
// des EU-Shops) in der offiziellen Ausgabegröße 1200 px Breite, Motiv unverändert; einheitlich ≤ 1600 px lange Kante, WebP q82 (tools/images/optimize-katalog.mjs).
// Titel in `name` unverändert (Shop-Titel); Slug = assouline-<Shop-Handle>.

const STAND = "2026-10-31";
const T = (de, en, fr, it) => Object.freeze({ de, en, fr, it });
const mass = (key, wert) => Object.freeze({ key, wert });
const L = ["de", "en", "fr", "it"];
const tx = (x, l) => (typeof x === "string" ? x : x[l]);

// ---------------------------------------------------------------- Vokabular
const TYP = {
  bildband: T("Bildband", "Illustrated book", "Beau livre", "Libro illustrato"),
  geschenkset: T("Geschenkset", "Gift set", "Coffret cadeau", "Set regalo"),
  duftkerze: T("Duftkerze", "Scented candle", "Bougie parfumée", "Candela profumata"),
  diffuser: T("Raumduft-Diffuser", "Home diffuser", "Diffuseur de parfum", "Diffusore per ambienti"),
  Objects: T("Objekt", "Object", "Objet", "Oggetto"),
  Stationery: T("Schreibwaren-Artikel", "Stationery item", "Article de papeterie", "Articolo di cartoleria"),
  Accessories: T("Accessoire", "Accessory", "Accessoire", "Accessorio"),
  "Candle Accessories": T("Kerzen-Zubehör", "Candle accessory", "Accessoire pour bougie", "Accessorio per candela"),
  Slipcase: T("Schuber", "Slipcase", "Étui", "Cofanetto"),
  Supplies: T("Accessoire", "Accessory", "Accessoire", "Accessorio"),
  "gift box": T("Geschenkbox", "Gift box", "Boîte cadeau", "Scatola regalo"),
  Extra: T("Accessoire", "Accessory", "Accessoire", "Accessorio"),
  "": T("Objekt", "Object", "Objet", "Oggetto"),
};
const SPRACHE = {
  English: T("Englisch", "English", "anglais", "inglese"),
  Français: T("Französisch", "French", "français", "francese"),
  Italiano: T("Italienisch", "Italian", "italien", "italiano"),
  Español: T("Spanisch", "Spanish", "espagnol", "spagnolo"),
  Deutsch: T("Deutsch", "German", "allemand", "tedesco"),
  Arabic: T("Arabisch", "Arabic", "arabe", "arabo"),
};
const AUSF = {
  hardcover: T("Hardcover", "hardcover", "relié", "copertina rigida"),
  softcover: T("Softcover", "softcover", "broché", "brossura"),
  clamshell: T("Kassette (Clamshell)", "clamshell case", "coffret clamshell", "cofanetto clamshell"),
  slipcase: T("Schuber", "slipcase", "étui", "custodia"),
  kiste: T("Holzkiste", "wooden crate", "caisse en bois", "cassa di legno"),
  hand: T("handgefertigt", "handcrafted", "fait main", "realizzato a mano"),
};
const MAT = {
  seide: T("Seide", "silk", "soie", "seta"),
  leinen: T("Leinen", "linen", "lin", "lino"),
  canvas: T("Canvas", "canvas", "toile", "tela"),
  leder: T("Leder", "leather", "cuir", "pelle"),
  holz: T("Holz", "wood", "bois", "legno"),
  acryl: T("Acryl", "acrylic", "acrylique", "acrilico"),
  samt: T("Samt", "velvet", "velours", "velluto"),
  vinyl: T("Vinyl", "vinyl", "vinyle", "vinile"),
  metall: T("Metall", "metal", "métal", "metallo"),
};
const MONAT = [
  ["Januar", "January", "janvier", "gennaio"], ["Februar", "February", "février", "febbraio"], ["März", "March", "mars", "marzo"],
  ["April", "April", "avril", "aprile"], ["Mai", "May", "mai", "maggio"], ["Juni", "June", "juin", "giugno"],
  ["Juli", "July", "juillet", "luglio"], ["August", "August", "août", "agosto"], ["September", "September", "septembre", "settembre"],
  ["Oktober", "October", "octobre", "ottobre"], ["November", "November", "novembre", "novembre"], ["Dezember", "December", "décembre", "dicembre"],
];
/** Generische Reihen (Sammelkollektionen) – nicht als „Reihe“ im Kurztext nennen. */
const GENERISCH = new Set(["Books", "Objects & Accessories", "Home Fragrance"]);
const Q = { de: ["„", "“"], en: ["“", "”"], fr: ["« ", " »"], it: ["«", "»"] };
const liste = (xs, l) => xs.map((x) => tx(x, l)).join(", ");
const kgText = (kg) => (kg < 1 ? `${Math.round(kg * 1000)} g` : `${String(kg).replace(".", ",")} kg`);

function kurz(r) {
  const typ = TYP[r.t] || TYP[""];
  const reihe = !GENERISCH.has(r.serie);
  const s1 = {
    de: `${typ.de} ${Q.de[0]}${r.n}${Q.de[1]} von Assouline${reihe ? ` aus der Reihe ${r.serie}` : ""}.`,
    en: `${typ.en} ${Q.en[0]}${r.n}${Q.en[1]} by Assouline${reihe ? ` from the ${r.serie} series` : ""}.`,
    fr: `${typ.fr} ${Q.fr[0]}${r.n}${Q.fr[1]} d'Assouline${reihe ? `, série ${r.serie}` : ""}.`,
    it: `${typ.it} ${Q.it[0]}${r.n}${Q.it[1]} di Assouline${reihe ? `, serie ${r.serie}` : ""}.`,
  };
  const teile = (l) => {
    const t = [];
    if (r.seiten) t.push({ de: `${r.seiten} Seiten`, en: `${r.seiten} pages`, fr: `${r.seiten} pages`, it: `${r.seiten} pagine` }[l]);
    if (r.sprache) t.push({ de: "Sprache: ", en: "language: ", fr: "langue : ", it: "lingua: " }[l] + liste(r.sprache.map((s) => SPRACHE[s]), l));
    if (r.ausf?.length) t.push({ de: "Ausführung: ", en: "edition: ", fr: "présentation : ", it: "formato: " }[l] + liste(r.ausf.map((a) => AUSF[a]), l));
    return t;
  };
  return T(...L.map((l) => {
    const t = teile(l);
    if (!t.length) return s1[l];
    const s2 = t.join(", ");
    return `${s1[l]} ${s2.charAt(0).toUpperCase()}${s2.slice(1)}.`;
  }));
}

function merkmale(r) {
  const m = [];
  if (r.autor) m.push(T(`Autor: ${r.autor}`, `Author: ${r.autor}`, `Auteur : ${r.autor}`, `Autore: ${r.autor}`));
  if (r.foto) m.push(T(`Fotografie: ${r.foto}`, `Photography: ${r.foto}`, `Photographie : ${r.foto}`, `Fotografia: ${r.foto}`));
  if (r.seiten) m.push(T(`${r.seiten} Seiten`, `${r.seiten} pages`, `${r.seiten} pages`, `${r.seiten} pagine`));
  if (r.ill) {
    const [ueber, z] = r.ill;
    m.push(ueber ? T(`Über ${z} Abbildungen`, `Over ${z} illustrations`, `Plus de ${z} illustrations`, `Oltre ${z} illustrazioni`) : T(`${z} Abbildungen`, `${z} illustrations`, `${z} illustrations`, `${z} illustrazioni`));
  }
  if (r.sprache) m.push(T(...L.map((l) => ({ de: "Sprache: ", en: "Language: ", fr: "Langue : ", it: "Lingua: " })[l] + liste(r.sprache.map((s) => SPRACHE[s]), l))));
  if (r.ausf?.length) m.push(T(...L.map((l) => ({ de: "Ausführung: ", en: "Edition: ", fr: "Présentation : ", it: "Formato: " })[l] + liste(r.ausf.map((a) => AUSF[a]), l))));
  if (r.mat?.length) m.push(T(...L.map((l) => ({ de: "Materialien (Einband/Kassette): ", en: "Materials (cover/case): ", fr: "Matériaux (couverture/coffret) : ", it: "Materiali (copertina/cofanetto): " })[l] + liste(r.mat.map((a) => MAT[a]), l))));
  if (r.erschienen) {
    const [mo, j] = r.erschienen;
    m.push(T(`Erscheinungstermin: ${MONAT[mo][0]} ${j}`, `Release date: ${MONAT[mo][1]} ${j}`, `Date de parution : ${MONAT[mo][2]} ${j}`, `Data di uscita: ${MONAT[mo][3]} ${j}`));
  }
  if (r.isbn) m.push(`ISBN ${r.isbn}`);
  return m;
}

function produkt(r) {
  const name = r.n;
  const masse = [r.dim && mass("abmessung", `${r.dim[0]} × ${r.dim[1]} × ${r.dim[2]} cm (W × L × D)`), r.kg && mass("gewicht", kgText(r.kg))].filter(Boolean);
  const variante = { name: r.k === "bildband" ? T("Ausgabe laut Shop", "Edition as listed", "Édition proposée", "Edizione in vendita") : T("Artikel laut Shop", "Item as listed", "Article proposé", "Articolo in vendita"), betrag: r.betrag };
  if (r.sku) variante.sku = r.sku;
  if (r.g) variante.versandGewichtG = r.g;
  const preis = r.betrag ? Object.freeze({ art: "verkaufspreis", varianten: Object.freeze([Object.freeze(variante)]), stand: STAND, quelle: r.url }) : undefined;
  const bilder = r.img
    ? [
        Object.freeze({
          src: `/Images/Wellness/produkte/assouline/${r.img[0]}`,
          width: r.img[1],
          height: r.img[2],
          alt: r.k === "bildband" || r.k === "geschenkset"
            ? T(`Assouline ${name} – Cover bzw. Produktfoto des Verlags`, `Assouline ${name} – publisher's cover or product photo`, `Assouline ${name} – couverture ou photo produit de l'éditeur`, `Assouline ${name} – copertina o foto prodotto dell'editore`)
            : T(`Assouline ${name} – Produktfoto des Herstellers`, `Assouline ${name} – manufacturer's product photo`, `Assouline ${name} – photo produit du fabricant`, `Assouline ${name} – foto prodotto del produttore`),
          quelleUrl: r.img[3],
          abgerufen: STAND,
        }),
      ]
    : [];
  return Object.freeze({
    slug: `assouline-${r.s}`,
    marke: "assouline",
    bereich: "accessoires",
    kategorie: r.k,
    name,
    serie: r.serie,
    kurz: kurz(r),
    merkmale: Object.freeze(merkmale(r)),
    ...(masse.length ? { masse: Object.freeze(masse) } : {}),
    bilder: Object.freeze(bilder),
    herstellerUrl: r.url,
    quellen: Object.freeze([r.url]),
    stand: STAND,
    ...(preis ? { preis } : {}),
  });
}

/** @type {import("../schema.js").KatalogMarke} */
export const MARKE = Object.freeze({
  slug: "assouline",
  name: "Assouline",
  welt: "accessoires",
  herstellerUrl: "https://eu.assouline.com/",
  // Händlersatz nur über den Claim-Guard (dealerStatement); hier nur der Schalter.
  dealer: true,
  stand: STAND,
});

